export class InputHandler {
  private dataStore: { state: number; events: { type: 'start' | 'pause' | 'resume' | 'stop'; timestamp: number }[] };

  constructor(dataStore: { state: number; events: { type: 'start' | 'pause' | 'resume' | 'stop'; timestamp: number }[] }) {
    this.dataStore = dataStore;
  }

  handleInput(event: { type: 'start' | 'pause' | 'resume' | 'stop'; userId: string; status?: string }): void {
    try {
      const currentEvent = { ...event };

      switch (currentEvent.type) {
        case 'start':
          this.startPomodoro(currentEvent);
          break;
        case 'pause':
          this.pausePomodoro(currentEvent);
          break;
        case 'resume':
          this.resumePomodoro(currentEvent);
          break;
        case 'stop':
          this.stopPomodoro(currentEvent);
          break;
        default:
          console.error('Unknown event type:', currentEvent.type);
          throw new Error('Unknown event type');
      }
    } catch (err) {
      console.error('Failed to handle input:', err);
    }
  }

  private startPomodoro(event: { userId: string; status?: string }): void {
    this.dataStore.state = 0;
    this.dataStore.events.push({ type: 'start', timestamp: Date.now() });
    console.log(`Started Pomodoro for user ${event.userId}`);
  }

  private pausePomodoro(event: { userId: string; status?: string }): void {
    this.dataStore.state = 1;
    this.dataStore.events.push({ type: 'pause', timestamp: Date.now() });
    console.log(`Paused Pomodoro for user ${event.userId}`);
  }

  private resumePomodoro(event: { userId: string; status?: string }): void {
    this.dataStore.state = 2;
    this.dataStore.events.push({ type: 'resume', timestamp: Date.now() });
    console.log(`Resumed Pomodoro for user ${event.userId}`);
  }

  private stopPomodoro(event: { userId: string; status?: string }): void {
    this.dataStore.state = 3;
    this.dataStore.events.push({ type: 'stop', timestamp: Date.now() });
    console.log(`Stopped Pomodoro for user ${event.userId}`);
  }
}

