    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    int line_count = 0;
    int word_count = 0;
    int char_count = 0;
    bool in_word = false;

    char ch;
    while ((ch = fgetc(file)) != EOF) {
        char_count++;
        if (ch == '\n') {
            line_count++;
        }
        if (isspace(ch)) {
            in_word = false;
        } else {
            if (!in_word) {
                word_count++;
                in_word = true;
            }
        }
    }

    fclose(file);
    return (WordCount){line_count, word_count, char_count};
}

