                buf[blen++] = (char)c;
            }
        } else if (blen > 0) {
            buf[blen] = '\0';
            if (n < MAX_WORDS) {
                strcpy(words[n], buf);
                n++;
            }
            blen = 0;
        }
    }
    if (blen > 0 && n < MAX_WORDS) {
        buf[blen] = '\0';
        strcpy(words[n], buf);
        n++;
    }

    size_t distinct = 0;
    for (size_t i = 0; i < n; i++) {
        int seen = 0;
        for (size_t j = 0; j < i; j++) {
            if (strcmp(words[i], words[j]) == 0) {
                seen = 1;
                break;
