            if (values[j] > values[j + 1]) {
                int tmp = values[j];
                values[j] = values[j + 1];
                values[j + 1] = tmp;
            }
        }
    }
    for (int i = 0; i < length; i++) {
        printf(i ? ",%d" : "%d", values[i]);
    }
    printf("\n");
    return 0;
}

