#include <stdio.h>
#include <string.h>

#define CAPACITY 32

struct stack {
    int items[CAPACITY];
    int size;
};

static void push(struct stack *s, int value) {
    if (s->size < CAPACITY) {
        s->items[s->size] = value;
        s->size += 1;
    }
}

static int pop(struct stack *s, int *value) {
    if (s->size == 0) {
        return 0;
    }
    *value = s->items[s->size - 1];
    s->size -= 1;
    return 1;
}

static int peek(const struct stack *s, int *value) {
    if (s->size == 0) {
        return 0;
    }
    *value = s->items[s->size - 1];
    return 1;
}

int main(void) {
    const char *ops[] = {
    "push 3",
    "push 1",
    "peek",
    "pop",
    "push 4",
    "pop",
    "pop",
    };
    struct stack s = {{0}, 0};
    char name[8];
    int value = 0;
    int count = (int)(sizeof(ops) / sizeof(ops[0]));
    for (int i = 0; i < count; i++) {
        if (sscanf(ops[i], "%7s %d", name, &value) == 2) {
            push(&s, value);
            printf("push %d\n", value);
        } else if (strcmp(ops[i], "pop") == 0) {
            if (pop(&s, &value)) {
                printf("pop %d\n", value);
            } else {
                printf("pop empty\n");
            }
        } else {
            if (peek(&s, &value)) {
                printf("peek %d\n", value);
            } else {
                printf("peek empty\n");
            }
        }
    }
    return 0;
}

