#include <stdio.h>
#include <string.h>

#define MAX_ROWS 8

static int parse(const char *data, char first[16], char second[16],
                 int *left, int *right) {
    char buffer[512];
    strncpy(buffer, data, sizeof(buffer) - 1);
    buffer[sizeof(buffer) - 1] = '\0';
    int rows = 0;
    char *line = strtok(buffer, "\n");
    if (line == NULL) {
        return 0;
    }
    sscanf(line, "%*[^,],%15[^,],%15[^,]", first, second);
    while ((line = strtok(NULL, "\n")) != NULL && rows < MAX_ROWS) {
        int a = 0;
        int b = 0;
        if (sscanf(line, "%*[^,],%d,%d", &a, &b) == 2) {
            *left += a;
            *right += b;
            rows += 1;
        }
    }
    return rows;
}

int main(void) {
    char first[16] = "";
    char second[16] = "";
    int left = 0;
    int right = 0;
    int rows = parse("name,qty,price\nbolt,12,1\nnut,40,2\nwasher,0,3", first, second, &left, &right);
    printf("columns %s,%s\n", first, second);
    printf("%s: %d\n", first, left);
    printf("%s: %d\n", second, right);
    printf("rows %d\n", rows);
    return 0;
}

