import "fmt"

type item struct {
	name  string
	qty   int
	price float64
}

func available(items []item) []item {
	out := []item{}
	for _, entry := range items {
		if entry.qty > 0 {
			out = append(out, entry)
		}
	}
	return out
}

func total(items []item) float64 {
	sum := 0.0
	for _, entry := range items {
		sum += float64(entry.qty) * entry.price
	}
	return sum
}

