	stock := []item{
		{"bolt", 12, 0.50},
		{"nut", 40, 0.10},
		{"washer", 0, 0.05},
	}
	rows := available(stock)
	for _, entry := range rows {
		fmt.Printf("%-8s %3d x %6.2f = %8.2f\n",
			entry.name, entry.qty, entry.price, float64(entry.qty)*entry.price)
	}
	fmt.Printf("total %.2f\n", total(rows))
}

