		"pop",
		"pop",
	}
	stack := &Stack{}
	for _, op := range ops {
		parts := strings.Fields(op)
		switch parts[0] {
		case "push":
			pushed, _ := strconv.Atoi(parts[1])
			stack.Push(pushed)
