public class CsvReaderMain {
    public static void main(String[] args) {
        if (args.length != 1) {
            System.out.println("Usage: java -jar csvreader.jar <input.csv>");
            return;
        }

        // Parsing arguments and initializing components.
       String inputPath = args[0];
        try (BufferedReader reader = new BufferedReader(new FileReader(inputPath))) {
            String headerLine = reader.readLine();
           if (headerLine == null) {
                System.out.println("The CSV file is empty.");
                 return;
           }
             String[] columnNames = headerLine.split(",");

              Map<String, List<Double>> numericColumns = new HashMap<>();
               for (String columnName : columnNames) {
                   try {
                      double value = Double.parseDouble(columnName);
                       numericColumns.put(columnName, new ArrayList<>());
                     } catch (NumberFormatException e) {
                         // Skip non-numeric columns for statistics.
                     }
                 }

                // Initializing data store.
                String line;
               int lineNumber = 0;
              while ((line = reader.readLine()) != null) {
                   lineNumber++;
                    String[] splits = line.split(",");

                      for(int i=0;i<splits.length;i++) 
                        {           
                          if( numericColumns.containsKey(columnNames[i])&& !splits[i].isEmpty())
                           {
                             double number=Double.parseDouble(splits[i]);
                              List<Double>values=numericColumns.get(columnNames[i]);
                            values.add(number);
                           }
                        }
                 }

            // Printing statistics
           for (Map.Entry<String, List<Double>> entry : numericColumns.entrySet()) {
               String columnName = entry.getKey();
                List<Double> values = entry.getValue();

               if (values.size() == 0) continue;

                double minVal = Double.MAX_VALUE;
                double maxVal = Double.MIN_VALUE;
              double sum = 0.0;

                for (double val : values) {
                      if (val < minVal) minVal = val;
                        if (val > maxVal) maxVal = val;
                          sum += val;
                     }

                 System.out.printf("Column: %s%n", columnName);
                 double mean=sum/values.size();
                  System.out.printf("  count=%d mean=%.2f\n", values.size(), mean);
              }
        } catch (IOException e) {
          System.err.println("Failed to read file: " + inputPath);
      }

    }
}

