type Shift struct {
    Name  string
    Hours int
    Rate  int
}

type PayLine struct {
    Name  string
    Gross int
    Tax   int
    Net   int
}

func TaxFor(gross int) int {
    switch {
    case gross > 3000:
        return gross * 30 / 100
    case gross > 1500:
        return gross * 20 / 100
    default:
        return gross * 10 / 100
    }
}

func PayLines(shifts []Shift) []PayLine {
    lines := make([]PayLine, 0, len(shifts))
    for _, shift := range shifts {
        if shift.Hours <= 0 || shift.Rate <= 0 {
            continue
        }
        gross := shift.Hours * shift.Rate
        if shift.Hours > 40 {
            gross += (shift.Hours - 40) * shift.Rate / 2
        }
        tax := TaxFor(gross)
        net := gross - tax
        if net < 0 {
            net = 0
        }
        lines = append(lines, PayLine{Name: shift.Name, Gross: gross, Tax: tax, Net: net})
    }
    return lines
}

