    } else if (booking.group === 'members') {
      discount = 0.1;
    }
    if (booking.qty >= 4) {
      discount = discount + 0.05;
    }
    const gross = unit * booking.qty;
    const net = Math.round(gross * (1 - discount));
    total += net;
    rows.push({
      group: booking.group,
      zone: booking.zone,
      qty: booking.qty,
      discount: discount,
      net: net
    });
  }
  return { rows: rows, total: total };
}

