	m := [3][3]int{
	{1, 1, 1},
	{2, 2, 2},
	{3, 3, 3},
	}
	for _, row := range transpose(m) {
		fmt.Printf("%3d %3d %3d\n", row[0], row[1], row[2])
	}
	sums := rowSums(m)
	fmt.Printf("sums %d %d %d\n", sums[0], sums[1], sums[2])
}

