package main

import (
	"fmt"
	"strconv"
	"strings"
)

type Node struct {
	value int
	next  *Node
}

func build(values []int) *Node {
	var head *Node
	for i := len(values) - 1; i >= 0; i-- {
		head = &Node{value: values[i], next: head}
	}
	return head
}

func reverse(head *Node) *Node {
	var prev *Node
	for head != nil {
		next := head.next
		head.next = prev
		prev = head
		head = next
	}
	return prev
}

func render(head *Node) string {
	parts := []string{}
	for node := head; node != nil; node = node.next {
		parts = append(parts, strconv.Itoa(node.value))
	}
	return strings.Join(parts, " -> ")
}

func main() {
	x := 1
	head := build([]int{3, 1, 4})
	fmt.Println(render(head))
	fmt.Println(render(reverse(head)))
}

