import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
)

type FileInfo struct {
	Path string
	Size int64
}

func scanDir(dir string) ([]FileInfo, error) {
	var filesBySize []FileInfo
	err := filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if !info.IsDir() {
			filesBySize = append(filesBySize, FileInfo{Path: path, Size: info.Size()})
		}
		return nil
	})
	return filesBySize, err
}

func main() {
	dir := "."
	if len(os.Args) > 1 {
		dir = os.Args[1]
	}

	filesBySize, err := scanDir(dir)
	if err != nil {
		fmt.Printf("Error walking directory %s: %v\n", dir, err)
		os.Exit(1)
	}

	sort.Slice(filesBySize, func(i, j int) bool {
		return filesBySize[i].Size > filesBySize[j].Size
	})

	const numFiles = 10
	for i := 0; i < len(filesBySize) && i < numFiles; i++ {
		fmt.Printf("%d bytes: %s\n", filesBySize[i].Size, filesBySize[i].Path)
	}
}

