    count = 1
    for ch in text[1:]:
        if ch == current:
            count = count + 1
        else:
            out.append((current, count))
            current = ch
            count = 1
    out.append((current, count))
    return out


def decode(pairs):
    parts = []
    for ch, count in pairs:
        parts.append(ch * count)
    return "".join(parts)


def summarise(text):
    pairs = encode(text)
    longest = 0
    compact = ""
    for ch, count in pairs:
        if count > longest:
            longest = count
        compact = compact + ch + str(count)
    return {"pairs": pairs, "runs": len(pairs), "longest": longest,
            "compact": compact, "round_trip": decode(pairs) == text}

# Card numbers and the digit the Luhn rule says they should end with.

NUMBERS = [
    "4539578763621486",
    "6011111111111117",
    "79927398713",
    "79927398710",
    "4222222222222",
]


def digits_of(text):
    out = []
    for ch in text:
        if ch.isdigit():
            out.append(int(ch))
    return out


def describe(number):
    digits = digits_of(number)
    if not digits:
        return "empty", 0
    total = 0
    doubled = 0
    for position, digit in enumerate(reversed(digits)):
        if position % 2 == 1:
            value = digit * 2
            if value > 9:
                value = value - 9
            doubled = doubled + 1
            total = total + value
        else:
            total = total + digit
    if len(digits) < 2:
        return "short", total
    if total % 10 == 0:
        return "ok", total
    return "invalid", total


def summarise(numbers):
    rows = []
    ok = 0
    longest = 0
    for number in numbers:
        status, total = describe(number)
        if status == "ok":
            ok = ok + 1
        if len(number) > longest:
            longest = len(number)
        rows.append((number, total, total % 10, status))
    return {"rows": rows, "ok": ok, "longest": longest,
            "count": len(numbers)}

# A small weighted graph and the distances out of one fixed start.

EDGES = [
    ("a", "b", 7), ("a", "c", 9), ("a", "f", 14),
    ("b", "c", 10), ("b", "d", 15),
    ("c", "d", 11), ("c", "f", 2),
    ("d", "e", 6),
    ("e", "f", 9),
]
START = "a"


def neighbours(edges, node):
    out = []
    for left, right, weight in edges:
        if left == node:
            out.append((right, weight))
        elif right == node:
            out.append((left, weight))
    return out


def distances(edges, start):
    nodes = []
    for left, right, weight in edges:
        if left not in nodes:
            nodes.append(left)
        if right not in nodes:
            nodes.append(right)
    dist = {}
    for node in nodes:
        dist[node] = None
    dist[start] = 0
    done = []
    while len(done) < len(nodes):
        best = None
        for node in nodes:
            if node in done or dist[node] is None:
                continue
            if best is None or dist[node] < dist[best]:
                best = node
        if best is None:
            break
        done.append(best)
        for other, weight in neighbours(edges, best):
            candidate = dist[best] + weight
            if dist[other] is None or candidate < dist[other]:
                dist[other] = candidate
    return dist


def summarise(edges, start):
    dist = distances(edges, start)
    order = []
    total = 0
    for node in sorted(dist):
        value = dist[node]
        order.append((node, value))
        if value is not None:
            total = total + value
    return {"order": order, "total": total, "nodes": len(order),
            "start": start}

