package main

import "math"

// FirstPrimes returns the first n prime numbers using trial division.
func FirstPrimes(n int) []int {
	if n <= 0 {
		return nil
	}
	primes := make([]int, 0, n)
	candidate := 2
	for len(primes) < n {
		if isPrime(candidate) {
			primes = append(primes, candidate)
		}
		candidate++
	}
	return primes
}

// isPrime checks whether num is prime via trial division up to sqrt(num).
func isPrime(num int) bool {
	if num < 2 {
		return false
	}
	if num == 2 {
		return true
	}
	if num%2 == 0 {
		return false
	}
	limit := int(math.Sqrt(float64(num)))
	for i := 3; i <= limit; i += 2 {
		if num%i == 0 {
			return false
		}
	}
	return true
}

